/// <summary>
/// dedine N.Freidenberger 21-07-2025
/// </summary>
/// <param name = "_printInMemory">_printInMemory</param>
/// <returns>parmPrintInMemory</returns>
public boolean parmAVAPrintInMemory(boolean    _avaprintInMemory = AVAprintInMemory)
{
    AVAprintInMemory = _avaprintInMemory;
    return AVAprintInMemory;
}

/// <summary>
/// N.Freidenberger 22-07-2025
/// </summary>
/// <param name = "_avaReportRecord">_avaReportRecord</param>
/// <returns>Common</returns>
public Common parmAVAreportRecord(Common    _avaReportRecord = AVAReportRecord)
{
    AVAReportRecord = _avaReportRecord;
    return avaReportRecord;
}

/// <summary>
/// N.Freidenberger 22-07-2025
/// </summary>
protected void preRunModifyContract()
{
    next preRunModifyContract();

    reportContract.parmDoNotSaveFileIM(this.parmAVAprintInMemory());
    reportContract.parmReportRecordIM(this.parmAVAreportRecord());
}

/// <summary>
/// N.Freidenberger 22-07-2025
/// </summary>
public void run()
{
    next run();

    System.Byte[] reportBytes = reportContract.parmReportBytesIM();
    if (reportBytes != null)
    {
        AVASrsReportDestinationHelper::saveToMemory(this.parmReportName(),reportBytes,reportContract.parmReportRecordIM());
    }
}
